import io

path = 'Системный_промт_для_приложения_КИПиА.md'
s = io.open(path, encoding='utf-8').read()

def rep(old, new, cnt=1, label=''):
    global s
    found = s.count(old)
    assert found == cnt, 'FAIL %s: найдено %d, ожидалось %d' % (label, found, cnt)
    s = s.replace(old, new, 1)

NEW_HEAD = """> **Версия документа:** 2026-09-28 (post-Task 438 [заявка пользователя «В разделе Табель учёта рабочего времени при выводе на печать список кодов должен отображаться в сокращённом виде, формат верхнего текста переделай на "График работы / Сентябрь 2026 г. · вид табеля: полный", нижний текст убери, колонку "Часы" убери, в колонке "Перераб." только дни; сделай возможность сохранения в файл вместо html в PDF и Excel»]: ПЕЧАТЬ ТАБЕЛЯ — НОВЫЙ ФОРМАТ ЛИСТА + ЭКСПОРТ В PDF И EXCEL ВМЕСТО HTML. Полностью КЛИЕНТСКАЯ задача: index.html + sw.js + тесты; WorkSchedule.gs/Code.gs НЕ тронуты (srvVer 427) — серверные шаги НЕ требуются, Ctrl+Shift+R ×1–2 после деплоя Pages. (1) ШАПКА ПЕЧАТИ ИЗ ДВУХ СТРОК: «График работы» + «‹Месяц› ‹год› г. · вид табеля: …» — строка нормы (wsp-meta «Норма (40-час. неделя)…») и штамп «Распечатано» (wsp-printed) УДАЛЕНЫ вместе с CSS-правилами (норма остаётся в «Итогах учёта»/окне календаря); (2) СНОСКА ВНИЗУ ЛИСТА (wsp-foot «* — сокращённый предпраздничный…») УДАЛЕНА ЦЕЛИКОМ (CSS тоже); (3) КОЛОНКА «Часы» УДАЛЕНА (шапка + ячейки), «Перераб.» — ТОЛЬКО ДНИ («3» вместо «3/36»; 0 — «—»; подпись «дни»; ширина wsp-tot-over 14→12 мм); (4) КОДЫ — СОКРАЩЁННЫЙ ВИД: «КОД — short» (поле short справочника Task 388, фолбэк name у кодов вне канона); голая «.» больше НЕ дублируется в легаси-хвосте перечня (раскрыта слотом «Выходной»); (5) ЭКСПОРТ ВМЕСТО HTML: «Сохранить в файл» (standalone-HTML, Task 430) → ДВЕ кнопки «Сохранить PDF» и «Сохранить Excel»: PDF = _savePrintPdf (чистая модель _printModel → раскладка _printPdfLayout [A4-альбом 842×595 pt; шапка — только первая страница; лента дней — на каждой странице таблицы; строки режутся без разрыва; мероприятия/коды — под таблицей или отдельными страницами] → отрисовка canvas ×2 → JPEG → мини-писатель PDF _buildPdfDocument [DCTDecode passthrough, xref с байтовыми смещениями, qpdf-валидно]; имя «График_работы_‹Месяц›_‹год›.pdf»); Excel = _savePrintXlsx → _buildTabelWorkbook (писатель XLSX Task 430; лист «Табель»: та же шапка 2 строки, сетка Работник/дни/«Дни»/«Перераб.» БЕЗ «Часов» с ЦВЕТНЫМИ заливками кодов [динамические стили _wsTabelStylesXml], строка дней недели, закрепление xSplit=1/ySplit=5, «Мероприятия · …» и «Коды:» с сокращениями; имя «График_работы_‹Месяц›_‹год›.xlsx»); printGrid передаёт в диалог контекст {viewEmps, agg}; _savePrintFile УДАЛЁН (standalone-HTML остаётся документом предпросмотра-iframe); НОВЫЕ МЕТОДЫ: _printModel/_printEventsData/_printCodesData/_printPdfLayout/_buildPdfDocument/_printPdfPaintPage/_wsDataUrlBytes/_savePrintPdf/_wsTabelStylesXml/_wsTabelRows/_wsTabelSheetXml/_buildTabelWorkbook/_savePrintXlsx. SW kipia-test-v661→v662 (task438-bump-sw.py: guards v662→v663 + ассерты v661→v662 в 122 файлах tests; test-task438.js исключён), тесты 4509/0 (146 тест-файлов = 145 + test-task438.js ×43: SRC шапка/сноска/колонки/кнопки/методы/PDF-структура; VM _buildPrintHtml-формат, _printModel [дни/эффективные записи/usedCodes], _printEventsData, _printCodesData [порядок/short/«.»-не-дублируется], _printPdfLayout [пагинация], _buildPdfDocument [xref/DCTDecode/MediaBox], _buildTabelWorkbook [zip/лист/цвета/закрепление], _savePrintPdf/_savePrintXlsx [моки скачивания/тосты/ошибки]; адаптация 13 тест-файлов 341/342/343/360/361/362/364/375/430/431/432/433/434), браузер 39/39 (порт 8937, Playwright: диалог/кнопки, лист, iframe, РЕАЛЬНЫЕ скачивания PDF [qpdf --check без ошибок, pymupdf 842×595] и Excel [PK-zip 6 частей, содержимое листа], отмена, мобайл 375, 0 JS-ошибок), VLM ×2 (предпросмотр + рендер PDF — все пункты Да). DEPLOY-Task438-print-header-short-codes-pdf-xlsx.md — КЛИЕНТСКИЙ_ONLY. Независимость разделов Инструктажи/Мероприятия (Task 429) и автосоздание 419–423 НЕ тронуты. ТЕКУЩЕЕ СОСТОЯНИЕ: kip8test SW `kipia-test-v662` (guard v663), тесты 4509/0 (146 тест-файлов), index.html ~56.4 тыс. строк; боевой kip8 — SW `kipia-v479` (guard v480): Task 438 НЕ ПЕРЕНЕСЁН — после приёмки пользователем (перенос одним инкрементом kipia-v479→v480); десктопы kip8test-desktop/kip8-desktop — CI-автосинк при пуше index.html. СЛЕДУЮЩИЙ НОМЕР ЗАДАЧИ: 439 (в обоих репо).)
"""

# 1. новая шапка + понижение post-437 до «предыдущей»
rep("""> **Версия документа:** 2026-09-27 (post-Task 437 [перенос в kip8 — заявка пользователя «перенеси все изменения в kip8»]:""",
    NEW_HEAD + """> **Версия документа (предыдущая):** 2026-09-27 (post-Task 437 [перенос в kip8 — заявка пользователя «перенеси все изменения в kip8»]:""",
    1, 'шапка post-437 → предыдущая')

# 2. живая кэш-версия
rep("> **Текущая версия кэша:** `kipia-test-v661`",
    "> **Текущая версия кэша:** `kipia-test-v662`", 1, 'кэш-версия')

# 3. стек: строки и тесты
rep("весь код в одном `index.html` (~52.2",
    "весь код в одном `index.html` (~56.4", 1, 'стек строки')
rep("Тесты | Node.js + кастомный фреймворк (`tests/`, 4306 тестов, 138 тест-файлов,",
    "Тесты | Node.js + кастомный фреймворк (`tests/`, 4509 тестов, 146 тест-файлов,", 1, 'стек тесты')

# 4. правило «Перед началом работы» — ожидания тестов
rep("ожидается `4306 passed, 0 failed` (для kip8test; в kip8 — `4312 passed, 0 failed`)",
    "ожидается `4509 passed, 0 failed` (для kip8test; в kip8 — `4472 passed, 0 failed`)",
    1, 'ожидание тестов (правила)')

# 5. команда быстрой проверки — ожидание
rep("# Ожидается: 4306 passed, 0 failed (kip8test; в kip8 — 4312 passed, 0 failed)",
    "# Ожидается: 4509 passed, 0 failed (kip8test; в kip8 — 4472 passed, 0 failed)",
    1, 'ожидание тестов (команды)')

# 6. формат инкремента кэша в правилах
rep("Формат: `kipia-test-v661` → `kipia-test-v662` (для kip8test) или `kipia-v479` → `kipia-v480` (для kip8)",
    "Формат: `kipia-test-v662` → `kipia-test-v663` (для kip8test) или `kipia-v479` → `kipia-v480` (для kip8)",
    1, 'формат бампа')

io.open(path, 'w', encoding='utf-8').write(s)
print('промпт обновлён: шапка post-438, v662, 4509/0, ~56.4 тыс. строк')
